#include "cartmesh2d/grid/RectilinearMesh2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include "cartmesh2d/quality/SolverQuality2D.hpp"
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <vector>

using namespace cartmesh2d;

static std::string polygonKey(const TopologyMesh2D& t, const TopologyCell2D& c) {
    std::vector<std::pair<double,double>> p;
    for (auto id:c.vertices) p.push_back({t.vertices.at(id).point.x,t.vertices.at(id).point.y});
    std::sort(p.begin(),p.end()); std::ostringstream out; out << std::hexfloat;
    for (auto [x,y]:p) out<<x<<','<<y<<';';
    return out.str();
}
static std::array<double,4> bounds(const TopologyMesh2D& t,const TopologyCell2D& c) {
    double xmin=1e300,xmax=-1e300,ymin=1e300,ymax=-1e300;
    for(auto id:c.vertices){auto p=t.vertices.at(id).point;xmin=std::min(xmin,p.x);xmax=std::max(xmax,p.x);ymin=std::min(ymin,p.y);ymax=std::max(ymax,p.y);}
    return {xmin,xmax,ymin,ymax};
}
int main(int argc,char** argv){try{
    if(argc!=3) throw std::runtime_error("usage: generate_midpoint original.cm2d output-prefix");
    auto read=readCm2dTopology(argv[1]); if(!read.valid()) throw std::runtime_error(read.error);
    const auto& base=read.topology; std::vector<double>x,y;
    for(auto&v:base.vertices){x.push_back(v.point.x);y.push_back(v.point.y);}
    auto unique=[](std::vector<double>& a){std::sort(a.begin(),a.end());a.erase(std::unique(a.begin(),a.end()),a.end());}; unique(x);unique(y);
    if(x.size()!=401||y.size()!=33) throw std::runtime_error("unexpected baseline axes");
    std::vector<double> refined; refined.reserve(61); for(std::size_t j=0;j+1<y.size();++j){ refined.push_back(y[j]); if(j>=4) refined.push_back(std::midpoint(y[j],y[j+1])); } refined.push_back(y.back());
    if(refined.size()!=61) throw std::runtime_error("unexpected refined y count");
    const auto t=makeRectilinearMesh2D(x,refined); if(t.cells.size()!=24000) throw std::runtime_error("unexpected refined cells");
    std::map<std::string,std::size_t> baseFirst,refFirst; for(auto&c:base.cells){auto b=bounds(base,c);if(b[2]<y[4])++baseFirst[polygonKey(base,c)];}
    for(auto&c:t.cells){auto b=bounds(t,c);if(b[2]<y[4])++refFirst[polygonKey(t,c)];}
    if(baseFirst!=refFirst||baseFirst.size()!=1600) throw std::runtime_error("first four strip polygon set mismatch");
    for(std::size_t j=4;j+1<y.size();++j){double m=std::midpoint(y[j],y[j+1]);bool found=false;for(double v:refined)if(v==m)found=true;if(!found)throw std::runtime_error("missing midpoint");}
    double baseArea=0,refArea=0;for(auto&c:base.cells)baseArea+=c.geometryArea;for(auto&c:t.cells)refArea+=c.geometryArea;if(std::abs(baseArea-refArea)>1e-13*std::max(1.0,std::abs(baseArea)))throw std::runtime_error("domain area changed");
    std::size_t parents=0; double maxCoverageError=0; for(auto&pc:base.cells){auto pb=bounds(base,pc);double sum=0;std::size_t n=0;for(auto&cc:t.cells){auto b=bounds(t,cc);if(b[0]==pb[0]&&b[1]==pb[1]&&b[2]>=pb[2]&&b[3]<=pb[3]){sum+=cc.geometryArea;++n;}}if(n!=1&&n!=2)throw std::runtime_error("parent partition child count mismatch");maxCoverageError=std::max(maxCoverageError,std::abs(sum-pc.geometryArea));++parents;}
    auto q=evaluateSolverQuality2D(t); if(!q.valid()) throw std::runtime_error("refined Solver quality failed");
    std::string err;std::string p=argv[2];if(!writeCm2dTopology(t,p+".cm2d",&err)||!writeLegacyVtk2D(t,p+".vtk",&err))throw std::runtime_error(err);std::ofstream qo(p+".quality.json");qo<<solverQualityReportToJson(q);
    std::ofstream ro(p+".geometry.json");ro<<std::setprecision(17)<<"{\"baselineCells\":"<<base.cells.size()<<",\"refinedCells\":"<<t.cells.size()<<",\"xCount\":"<<x.size()<<",\"baselineYCount\":33,\"refinedYCount\":"<<refined.size()<<",\"firstFourStripPolygonSetIdentical\":true,\"insertedMidpointsProper\":true,\"domainAreaIdentical\":true,\"domainAreaAbsDifference\":"<<std::abs(baseArea-refArea)<<",\"parentPartitionCoverage\":true,\"parentsChecked\":"<<parents<<",\"maxCoverageError\":"<<maxCoverageError<<",\"qualityValid\":true}\n";
    std::cout<<"baselineCells="<<base.cells.size()<<" refinedCells="<<t.cells.size()<<" x="<<x.size()<<" y="<<refined.size()<<" parents="<<parents<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
